class LruCache<K, V> {
  private final int cap;
  private final LinkedHashMap<K, V> m;
  LruCache(int cap) {
    this.cap = cap;
    m = new LinkedHashMap<>(16, 0.75f, true) {
      protected boolean removeEldestEntry(Map.Entry<K, V> e) { return size() > LruCache.this.cap; }
    };
  }
  synchronized V get(K k) { return m.get(k); }
  synchronized void put(K k, V v) { m.put(k, v); }
}

class LRU:
    def __init__(self, cap):
        self.cap, self.d, self.lock = cap, OrderedDict(), threading.Lock()
    def get(self, key):
        with self.lock:
            if key not in self.d: return None
            self.d.move_to_end(key); return self.d[key]
    def put(self, key, value):
        with self.lock:
            self.d[key] = value; self.d.move_to_end(key)
            if len(self.d) > self.cap: self.d.popitem(last=False)

